// Longest substring without repeating characters (variable-size window).
int longestUnique(const string& s) {
    vector<int> last(256, -1);
    int left = 0, best = 0;
    for (int right = 0; right < (int)s.size(); ++right) {
        unsigned char c = s[right];
        if (last[c] >= left) left = last[c] + 1;   // shrink past the duplicate
        last[c] = right;
        best = max(best, right - left + 1);
    }
    return best;
}

def longest_unique_substring(s):
    seen = {}
    left = best = 0
    for right, c in enumerate(s):
        if c in seen and seen[c] >= left:
            left = seen[c] + 1      # shrink past the duplicate
        seen[c] = right
        best = max(best, right - left + 1)
    return best

class Solution {
public:
    double findMaxAverage(vector<int>& a, int k) {
        double sum = 0;
        for (int i = 0; i < k; i++) sum += a[i];
        double best = sum;
        for (int i = k; i < (int)a.size(); i++) { sum += a[i] - a[i - k]; best = max(best, sum); }
        return best / k;
    }
};

class Solution:
    def findMaxAverage(self, a: list[int], k: int) -> float:
        s = sum(a[:k])
        best = s
        for i in range(k, len(a)):
            s += a[i] - a[i - k]
            best = max(best, s)
        return best / k

class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        vector<int> last(128, -1);
        int l = 0, best = 0;
        for (int r = 0; r < (int)s.size(); r++) {
            if (last[s[r]] >= l) l = last[s[r]] + 1;
            last[s[r]] = r;
            best = max(best, r - l + 1);
        }
        return best;
    }
};

class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        last = {}
        l = best = 0
        for r, c in enumerate(s):
            if c in last and last[c] >= l:
                l = last[c] + 1
            last[c] = r
            best = max(best, r - l + 1)
        return best

class Solution {
public:
    int minSubArrayLen(int target, vector<int>& a) {
        int l = 0, sum = 0, best = INT_MAX;
        for (int r = 0; r < (int)a.size(); r++) {
            sum += a[r];
            while (sum >= target) { best = min(best, r - l + 1); sum -= a[l++]; }
        }
        return best == INT_MAX ? 0 : best;
    }
};

class Solution:
    def minSubArrayLen(self, target: int, a: list[int]) -> int:
        l = s = 0
        best = float('inf')
        for r, x in enumerate(a):
            s += x
            while s >= target:
                best = min(best, r - l + 1)
                s -= a[l]; l += 1
        return 0 if best == float('inf') else best

class Solution {
public:
    bool checkInclusion(string s1, string s2) {
        if (s1.size() > s2.size()) return false;
        vector<int> need(26, 0), win(26, 0);
        for (char c : s1) need[c - 'a']++;
        int k = s1.size();
        for (int i = 0; i < (int)s2.size(); i++) {
            win[s2[i] - 'a']++;
            if (i >= k) win[s2[i - k] - 'a']--;
            if (i >= k - 1 && win == need) return true;
        }
        return false;
    }
};

class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        if len(s1) > len(s2):
            return False
        need = [0] * 26
        win = [0] * 26
        for c in s1:
            need[ord(c) - 97] += 1
        k = len(s1)
        for i, c in enumerate(s2):
            win[ord(c) - 97] += 1
            if i >= k:
                win[ord(s2[i - k]) - 97] -= 1
            if i >= k - 1 and win == need:
                return True
        return False

class Solution {
public:
    string minWindow(string s, string t) {
        vector<int> need(128, 0);
        for (char c : t) need[c]++;
        int missing = t.size(), l = 0, bestLen = INT_MAX, bestL = 0;
        for (int r = 0; r < (int)s.size(); r++) {
            if (need[s[r]]-- > 0) missing--;
            while (missing == 0) {
                if (r - l + 1 < bestLen) { bestLen = r - l + 1; bestL = l; }
                if (++need[s[l++]] > 0) missing++;
            }
        }
        return bestLen == INT_MAX ? "" : s.substr(bestL, bestLen);
    }
};

from collections import Counter
class Solution:
    def minWindow(self, s: str, t: str) -> str:
        need = Counter(t)
        missing = len(t)
        l = best_l = 0
        best_len = float('inf')
        for r, c in enumerate(s):
            if need[c] > 0:
                missing -= 1
            need[c] -= 1
            while missing == 0:
                if r - l + 1 < best_len:
                    best_len, best_l = r - l + 1, l
                need[s[l]] += 1
                if need[s[l]] > 0:
                    missing += 1
                l += 1
        return "" if best_len == float('inf') else s[best_l:best_l + best_len]
